/bin/bash -c "python - <<'PY'
import cv2, numpy as np
im=cv2.imread('first_frame.png')
g=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY)
for t in [10,15,20,30,40,50]:
 e=cv2.Canny(g,20,t)
 lines=cv2.HoughLinesP(e,1,np.pi/360,threshold=12,minLineLength=8,maxLineGap=3)
 print('\\nTHRESH',t,'n',0 if lines is None else len(lines))
 if lines is not None:
  arr=[]
  for l in lines[:,0]:
   x1,y1,x2,y2=map(int,l); L=np.hypot(x2-x1,y2-y1); ang=np.degrees(np.arctan2(y2-y1,x2-x1))
   if L>=8: arr.append((L,ang,(x1,y1,x2,y2)))
  for x in sorted(arr,reverse=True)[:25]: print('%5.1f %6.1f %s'%x)
PY"
